INSERT INTO `tag` (`name`, `status`) SELECT 'Digital Marketing', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'Digital Marketing');
INSERT INTO `tag` (`name`, `status`) SELECT 'Google AI Overview', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'Google AI Overview');
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'WSQ');

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'generative-ai-seo-google-ai-overview-optimization');

